'use strict';

// MODULES //

var ndarraylike2scalar = require( '@stdlib/ndarray/base/ndarraylike2scalar' );
var numelDimension = require( '@stdlib/ndarray/base/numel-dimension' );
var getStride = require( '@stdlib/ndarray/base/stride' );
var getOffset = require( '@stdlib/ndarray/base/offset' );
var getData = require( '@stdlib/ndarray/base/data-buffer' );
var strided = require( '@stdlib/stats/base/snanstdevpn' ).ndarray;


// MAIN //

/**
* Computes the standard deviation of a one-dimensional single-precision floating-point ndarray, ignoring `NaN` values.
*
* @param {ArrayLikeObject<Object>} arrays - array-like object containing a one-dimensional input ndarray and a zero-dimensional ndarray specifying a degrees of freedom adjustment
* @returns {number} standard deviation
*
* @example
* var Float32Array = require( '@stdlib/array/float32' );
* var scalar2ndarray = require( '@stdlib/ndarray/from-scalar' );
* var ndarray = require( '@stdlib/ndarray/base/ctor' );
*
* var xbuf = new Float32Array( [ 1.0, 3.0, NaN, 2.0 ] );
* var x = new ndarray( 'float32', xbuf, [ 4 ], [ 1 ], 0, 'row-major' );
*
* var c = scalar2ndarray( 1.0, { 'dtype': 'float32' } );
*
* var v = snanstdev( [ x, c ] );
* // returns 1.0
*/
function snanstdev( arrays ) {
	var correction = ndarraylike2scalar( arrays[ 1 ] );
	var x = arrays[ 0 ];

	return strided(numelDimension( x, 0 ), correction, getData( x ), getStride( x, 0 ), getOffset( x )); // eslint-disable-line max-len
}


// EXPORTS //

module.exports = snanstdev;
